"""Same-artifact control: disable only the named QDQ selector/action pass."""

import gc
import time

import numpy as np
from support import (ART, RESULTS, baselines, checked, info, now, pilot,
                     profile_model, read, save_output, session, write)


def main():
    if (RESULTS / "fusion_control.json").exists():
        raise FileExistsError("Control already recorded")
    pass_name = "QDQSelectorActionTransformer"
    source = baselines()["qdq_all"]
    write(RESULTS / "fusion_control_protocol.json", {
        "locked_at_utc": now(), "model": source["model"], "disabled_pass": pass_name,
        "scope": "Supplementary causal control of this optimizer pass on the same graph, all other optimization levels retained. Does not isolate each Conv fusion from all other rules in the pass. Not used to select A/B.",
        "protocol": "Two conditions, 5 alternating-order rounds, 16 warmups plus16 timed development inputs/round; profiling in separate sessions after timing; 4 intra/1 inter threads, spinning off", "source_code": info(__file__)})
    data = pilot.load_datasets("mlsd")
    inputs = data["evaluation"][0].numpy()
    conditions = {"enabled": None, "disabled": [pass_name]}
    timings = {name: [] for name in conditions}
    outputs = {}
    for cycle in range(5):
        order = list(conditions) if cycle % 2 == 0 else list(conditions)[::-1]
        for name in order:
            runtime = session(checked(source["model"]), disabled_optimizers=conditions[name])
            for image in inputs:
                runtime.run(None, {"input": image[None]})
            result = []
            for image in inputs:
                start = time.perf_counter_ns()
                output = runtime.run(None, {"input": image[None]})[0]
                timings[name].append((time.perf_counter_ns() - start) / 1e6)
                if cycle == 0:
                    result.append(output)
            if cycle == 0:
                outputs[name] = np.concatenate(result).transpose(0, 2, 3, 1)
            del runtime
            gc.collect()
        print("FUSION CONTROL", cycle + 1, "/5", flush=True)
    profiles = {}
    for name in conditions:
        item = {**source, "disabled_optimizers": conditions[name]}
        profiles[name] = profile_model("fusion_pass_" + name, item, inputs)
    enabled = profiles["enabled"]["unique_operators"].get("QLinearConv", 0)
    disabled = profiles["disabled"]["unique_operators"].get("QLinearConv", 0)
    # Evidence must show the installed runtime recognized and disabled this pass.
    if enabled != 22 or disabled != 0:
        raise RuntimeError(f"Cannot validate pass control: {enabled} vs {disabled}")
    write(RESULTS / "fusion_control.json", {"measured_at_utc": now(),
          "protocol": info(RESULTS / "fusion_control_protocol.json"),
          "same_artifact": source["model"], "disabled_pass": pass_name,
          "named_pass_effect_confirmed": True,
          "conditions": {name: {"median_ms": float(np.median(values)),
                                 "p95_ms": float(np.percentile(values, 95)), "samples_ms": values,
                                 "runs": len(values), "profile": profiles[name],
                                 "development_output": save_output("fusion_pass_" + name + "_development", outputs[name]),
                                 "sAP10": pilot.line_metrics(outputs[name], data["ground_truth"])}
                         for name, values in timings.items()},
          "numeric_difference": pilot.numerical(outputs["disabled"], outputs["enabled"]),
          "scope": "Effect of named QDQ selector/action optimizer pass, not all optimization and not pure Conv-kernel cost. Same artifact/precision specification; numeric kernel rounding may differ.",
          "source_code": info(__file__)})


if __name__ == "__main__":
    main()

"""Frozen inputs and evidence helpers for the approved day-19 experiment."""

import gc
import hashlib
import json
import sys
from datetime import UTC, datetime
from pathlib import Path

import numpy as np
import onnxruntime as ort

TASK = Path(__file__).resolve().parents[1]
ROOT = TASK.parents[3]
ART = TASK / "artifacts"
RESULTS = TASK / "results"
DAY16 = ROOT / "daily/2026-10-16/experiments/finalize"
DAY15 = ROOT / "daily/2026-10-15/experiments/qat"
for folder in [DAY16 / "src", DAY15 / "src", ROOT / "daily/2026-10-14/experiments/qat/src"]:
    sys.path.append(str(folder))
from train_continue import pilot  # noqa: E402


def now():
    return datetime.now(UTC).isoformat()


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def write(path, value):
    path = Path(path)
    if path.exists():
        raise FileExistsError(f"Preserve recorded evidence: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False) + "\n",
                    encoding="utf-8", newline="\n")


def sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def info(path):
    path = Path(path)
    return {"path": path.resolve().relative_to(ROOT).as_posix(),
            "sha256": sha(path), "bytes": path.stat().st_size}


def checked(item):
    path = ROOT / item["path"]
    if sha(path) != item["sha256"]:
        raise ValueError(f"Evidence changed: {path}")
    return path


def session(path, optimization="all", optimized=None, profile=None, disabled_optimizers=None):
    options = ort.SessionOptions()
    options.intra_op_num_threads = 4
    options.inter_op_num_threads = 1
    options.execution_mode = ort.ExecutionMode.ORT_SEQUENTIAL
    options.graph_optimization_level = (ort.GraphOptimizationLevel.ORT_ENABLE_ALL
                                       if optimization == "all"
                                       else ort.GraphOptimizationLevel.ORT_DISABLE_ALL)
    options.add_session_config_entry("session.intra_op.allow_spinning", "0")
    options.log_severity_level = 3
    if optimized:
        options.optimized_model_filepath = str(optimized)
    if profile:
        options.enable_profiling = True
        options.profile_file_prefix = str(profile)
    return ort.InferenceSession(str(path), options, providers=["CPUExecutionProvider"],
                                disabled_optimizers=disabled_optimizers)


def infer(path, inputs, optimization="all"):
    runtime = session(path, optimization)
    values = [runtime.run(None, {"input": x[None]})[0] for x in inputs]
    del runtime
    gc.collect()
    outputs = np.concatenate(values).transpose(0, 2, 3, 1)
    if not np.isfinite(outputs).all():
        raise ValueError("Nonfinite inference output")
    return outputs


def save_output(name, output):
    path = ART / (name + ".npy")
    if path.exists():
        raise FileExistsError(path)
    np.save(path, output, allow_pickle=False)
    return info(path)


def baselines():
    selection = read(DAY16 / "results/mlsd_selection.json")
    deployment = read(DAY15 / "results/research/deployment.json")
    qdq = selection["candidates"]["frozen_qdq"]["model"]
    return {
        "teacher_fp32": {"model": deployment["artifacts"]["original_fp32_model"], "optimization": "all"},
        "custom_41_integer": {"model": deployment["artifacts"]["integer_model"], "optimization": "all"},
        "qdq_all": {"model": qdq, "optimization": "all"},
        "qdq_optimizer_off": {"model": qdq, "optimization": "off"},
    }


def block_name(name):
    parts = name.split(".")
    if "features" in parts:
        index = parts.index("features")
        return ".".join(parts[:index + 2])
    return ".".join(parts[:3])


def summarize_profile(trace_path, measured_runs=8):
    """Only the final measured model_run intervals; exclude warm-up and startup."""
    from collections import Counter, defaultdict

    events = read(trace_path)
    runs = [e for e in events if e.get("name") == "model_run"][-measured_runs:]
    if len(runs) != measured_runs:
        raise ValueError("Incomplete profile run intervals")
    kernels = [e for e in events if e.get("cat") == "Node"
               and e.get("name", "").endswith("_kernel_time")
               and any(r["ts"] <= e["ts"] < r["ts"] + r["dur"] for r in runs)]
    unique = {e["name"]: e["args"] for e in kernels}
    totals, nodes = Counter(), defaultdict(lambda: {"durations_ms": [], "args": None})
    for event in kernels:
        op = event["args"]["op_name"]
        totals[op] += event["dur"] / 1000 / measured_runs
        item = nodes[event["name"]]
        item["durations_ms"].append(event["dur"] / 1000)
        item["args"] = event["args"]
    return {
        "measured_runs": measured_runs,
        "unique_operators": dict(Counter(a["op_name"] for a in unique.values())),
        "providers": dict(Counter(a.get("provider", "unknown") for a in unique.values())),
        "operator_mean_ms": dict(totals),
        "mean_model_run_ms": float(np.mean([e["dur"] / 1000 for e in runs])),
        "nodes": [{"name": name, "op": item["args"]["op_name"],
                   "provider": item["args"].get("provider"),
                   "input_type_shape": item["args"].get("input_type_shape"),
                   "mean_ms": float(np.mean(item["durations_ms"])),
                   "calls": len(item["durations_ms"])} for name, item in nodes.items()],
        "trace": info(trace_path),
        "scope": "Warm profile, final 8 model_run intervals only; profiler overhead included; not benchmark latency",
    }


def profile_model(name, item, inputs):
    optimized = ART / f"{name}_optimized.onnx"
    if optimized.exists():
        raise FileExistsError(optimized)
    runtime = session(checked(item["model"]), item["optimization"], optimized,
                      ART / f"{name}_profile", item.get("disabled_optimizers"))
    for index in range(16):
        runtime.run(None, {"input": inputs[index % len(inputs)][None]})
    for index in range(8):
        runtime.run(None, {"input": inputs[index][None]})
    trace = Path(runtime.end_profiling())
    del runtime
    gc.collect()
    summary = summarize_profile(trace)
    summary["optimized_model"] = info(optimized)
    return summary
